"use client"

import { useInView, useMotionValue, useReducedMotion } from "motion/react"
import {
  useEffect,
  useMemo,
  useRef,
  type ComponentProps,
  type ReactNode,
} from "react"

import { cn } from "@/lib/utils"

import { FlowBeam } from "./beam"
import {
  FlowDiamond,
  FlowEdge,
  FlowLabel,
  FlowNode,
  FlowReveal,
  FlowSpinner,
  FlowStatusDot,
  FlowTypedText,
} from "./elements"
import { FlowClockContext, useFlowClock } from "./flow-clock"
import {
  FLOW_BEAM_SPEED,
  flowArrival,
  flowRoute,
  type FlowPoint,
  type FlowRoute,
} from "./route"
import type { FlowTone } from "./tone"

/**
 * 流程动画外框：点阵底纹 + 固定设计尺寸的 SVG，并提供统一的时间轴。
 *
 * 所有动画都由同一个 `time` 推导，渲染期间不依赖 Date / 随机数，水合结果稳定：
 * - 初始（含服务端渲染、减少动态效果）停在 `rest`，即内容完整、没有光点的一帧；
 * - 进入视口后从 `rest` 继续走完停留 → 淡出 → 重新开始，所以不会闪一下；
 * - 离开视口暂停，不占 CPU。
 */
function FlowDiagram({
  width = 216,
  height = 192,
  duration = 8,
  exit = duration - 0.8,
  rest = exit - 0.2,
  dots = true,
  label,
  className,
  children,
  ...props
}: Omit<ComponentProps<"div">, "children"> & {
  /**
   * 设计画布宽度。子元素的坐标都以它为准，实际显示时等比缩小到容器宽度
   * @default 216
   */
  width?: number
  /**
   * 设计画布高度
   * @default 192
   */
  height?: number
  /**
   * 一轮循环的总时长（秒）
   * @default 8
   */
  duration?: number
  /**
   * 从这一刻起内容淡出，循环末尾回到起点
   * @default duration - 0.8
   */
  exit?: number
  /**
   * 静帧停留的时刻：服务端渲染、首帧与“减少动态效果”下显示的就是这一刻的画面，
   * 应落在所有内容都已点亮、光点都已飞完之后、`exit` 之前
   * @default exit - 0.2
   */
  rest?: number
  /**
   * 是否显示向四周淡出的点阵底纹
   * @default true
   */
  dots?: boolean
  /** 图示的文字说明。传入后读屏会朗读它；不传则整个图示按纯装饰处理 */
  label?: string
  children?: ReactNode
}) {
  const ref = useRef<HTMLDivElement>(null)
  const inView = useInView(ref, { amount: 0.4 })
  const reducedMotion = useReducedMotion()
  const time = useMotionValue(rest)
  const playing = inView && !reducedMotion

  useEffect(() => {
    if (reducedMotion) time.set(rest)
  }, [reducedMotion, rest, time])

  useEffect(() => {
    if (!playing) return
    let last = performance.now()
    let frame = requestAnimationFrame(function tick(now) {
      // 切回标签页时间差会很大，截断后动画从原地继续而不是跳一大段
      const delta = Math.min((now - last) / 1000, 0.1)
      last = now
      time.set((time.get() + delta) % duration)
      frame = requestAnimationFrame(tick)
    })
    return () => cancelAnimationFrame(frame)
  }, [playing, duration, time])

  const clock = useMemo(
    () => ({ time, duration, exit }),
    [time, duration, exit],
  )

  return (
    <div
      {...props}
      ref={ref}
      data-slot="flow-diagram"
      {...(label
        ? { role: "img", "aria-label": label }
        : { "aria-hidden": true })}
      className={cn(
        "relative flex items-center justify-center overflow-hidden",
        className,
      )}
    >
      {dots ? (
        // 点阵底纹向四周淡出，让图示像摆在图纸上
        <div className="pointer-events-none absolute inset-0 bg-dots [mask-image:radial-gradient(ellipse_at_center,black_20%,transparent_80%)]" />
      ) : null}
      <svg
        viewBox={`0 0 ${width} ${height}`}
        width={width}
        height={height}
        fill="none"
        focusable="false"
        aria-hidden="true"
        className="relative h-auto max-w-full"
      >
        {/* 整体平移半像素，1px 的线落在像素中心，边缘才清晰 */}
        <g transform="translate(0.5 0.5)">
          <FlowClockContext.Provider value={clock}>
            {children}
          </FlowClockContext.Provider>
        </g>
      </svg>
    </div>
  )
}

export {
  FLOW_BEAM_SPEED,
  FlowBeam,
  FlowDiagram,
  FlowDiamond,
  FlowEdge,
  FlowLabel,
  FlowNode,
  FlowReveal,
  FlowSpinner,
  FlowStatusDot,
  FlowTypedText,
  flowArrival,
  flowRoute,
  useFlowClock,
}
export type { FlowPoint, FlowRoute, FlowTone }

"use client"

import { motion, useMotionValueEvent, useTransform } from "motion/react"
import { useMemo, useState, type ReactNode } from "react"

import { cn } from "@/lib/utils"

import type { FlowRoute } from "./route"
import { useFlowClock } from "./flow-clock"
import { toneClasses, type FlowTone } from "./tone"

/** 等宽字 10px 下的字符宽度，用来估算光标位置（中文按全角 10px 计） */
const LATIN_ADVANCE = 6
const CJK_ADVANCE = 10

type Box = { x: number; y: number; width: number; height: number; rx: number }

/** 在 `at` 秒淡入（可带上浮），停留到 `exit` 后随循环淡出。 */
function FlowReveal({
  at,
  rise = 0,
  fade = 0.3,
  children,
}: {
  /** 开始淡入的时刻（秒） */
  at: number
  /**
   * 淡入时从下方上浮的距离（设计尺寸中的像素）
   * @default 0
   */
  rise?: number
  /**
   * 淡入用时（秒）
   * @default 0.3
   */
  fade?: number
  children: ReactNode
}) {
  const { time, exit, duration } = useFlowClock()
  const opacity = useTransform(
    time,
    [at, at + fade, exit, duration],
    [0, 1, 1, 0],
  )
  const y = useTransform(time, [at, at + fade], [rise, 0])
  return (
    <motion.g data-slot="flow-reveal" style={{ opacity, y }}>
      {children}
    </motion.g>
  )
}

/** 节点被光点点亮后的状态层：主色（或警示色）描边加淡底色。 */
function Lit({ box, at, tone }: { box: Box; at: number; tone: FlowTone }) {
  const { time, exit, duration } = useFlowClock()
  const opacity = useTransform(
    time,
    [at, at + 0.25, exit, duration],
    [0, 1, 1, 0],
  )
  return (
    <motion.g style={{ opacity }}>
      <rect {...box} strokeWidth={1} className={toneClasses[tone].lit} />
    </motion.g>
  )
}

/**
 * 细边框小胶囊。`x`、`y` 是中心点；`litAt` 到达时，边框和底色换成主色。
 * 内部文字、图标请作为 `children` 传入，用 `FlowLabel` 等原语按绝对坐标摆放。
 */
function FlowNode({
  x,
  y,
  width,
  height = 20,
  radius = height / 2,
  litAt,
  litTone = "primary",
  children,
}: {
  /** 中心点的横坐标 */
  x: number
  /** 中心点的纵坐标 */
  y: number
  width: number
  /**
   * 节点高度
   * @default 20
   */
  height?: number
  /**
   * 圆角半径，缺省为高度的一半（胶囊），传小值得到方角的框
   */
  radius?: number
  /** 被点亮的时刻（秒），不传则不点亮 */
  litAt?: number
  /**
   * 点亮后的颜色
   * @default "primary"
   */
  litTone?: FlowTone
  children?: ReactNode
}) {
  const box: Box = {
    x: x - width / 2,
    y: y - height / 2,
    width,
    height,
    rx: radius,
  }
  return (
    <g data-slot="flow-node">
      <rect
        {...box}
        strokeWidth={1}
        className="fill-background stroke-foreground/30"
      />
      {litAt === undefined ? null : <Lit box={box} at={litAt} tone={litTone} />}
      {children}
    </g>
  )
}

/** 流程图里的分叉 / 汇合点：旋转 45° 的小方块。 */
function FlowDiamond({
  x,
  y,
  litAt,
  litTone = "primary",
}: {
  /** 中心点的横坐标 */
  x: number
  /** 中心点的纵坐标 */
  y: number
  /** 被点亮的时刻（秒），不传则不点亮 */
  litAt?: number
  /**
   * 点亮后的颜色
   * @default "primary"
   */
  litTone?: FlowTone
}) {
  const box: Box = { x: -4, y: -4, width: 8, height: 8, rx: 1.5 }
  return (
    <g data-slot="flow-diamond" transform={`translate(${x} ${y}) rotate(45)`}>
      <rect
        {...box}
        strokeWidth={1}
        className="fill-background stroke-foreground/30"
      />
      {litAt === undefined ? null : <Lit box={box} at={litAt} tone={litTone} />}
    </g>
  )
}

/** 等宽小标签，默认居中；颜色、字号用 `className` 覆盖。 */
function FlowLabel({
  x,
  y,
  anchor = "middle",
  className,
  children,
}: {
  /** 锚点的横坐标 */
  x: number
  /** 文字垂直中线的纵坐标 */
  y: number
  /**
   * 文字相对 `x` 的对齐方式
   * @default "middle"
   */
  anchor?: "start" | "middle" | "end"
  className?: string
  children: ReactNode
}) {
  return (
    <text
      data-slot="flow-label"
      x={x}
      y={y}
      textAnchor={anchor}
      dominantBaseline="central"
      className={cn("fill-foreground font-mono text-[10px]", className)}
    >
      {children}
    </text>
  )
}

/**
 * 逐字打出的文字，后面跟一个主色光标。
 * 已打出的字数由时间推导，不依赖定时器；`x` 是文字起点（左对齐）。
 */
function FlowTypedText({
  text,
  at,
  interval,
  x,
  y,
}: {
  text: string
  /** 开始打第一个字的时刻（秒） */
  at: number
  /** 每个字的间隔（秒） */
  interval: number
  /** 文字起点（左对齐）的横坐标 */
  x: number
  /** 文字垂直中线的纵坐标 */
  y: number
}) {
  const { time, exit, duration } = useFlowClock()
  const chars = useMemo(() => Array.from(text), [text])
  const typedCount = (value: number) =>
    Math.max(0, Math.min(chars.length, Math.floor((value - at) / interval) + 1))
  const [count, setCount] = useState(() => typedCount(time.get()))
  useMotionValueEvent(time, "change", (value) => setCount(typedCount(value)))

  const typed = chars.slice(0, count)
  const caretX =
    x +
    typed.reduce(
      (width, char) =>
        width + (char.charCodeAt(0) > 0xff ? CJK_ADVANCE : LATIN_ADVANCE),
      0,
    )
  const typingEnd = at + chars.length * interval
  // 打字时常亮，打完后闪几下就收起
  const caretOpacity = useTransform(time, (value) => {
    if (value < at || value > typingEnd + 0.9) return 0
    if (value < typingEnd) return 1
    return Math.floor((value - typingEnd) * 3) % 2 === 0 ? 1 : 0
  })
  const opacity = useTransform(time, [exit, duration], [1, 0])

  return (
    <motion.g data-slot="flow-typed-text" style={{ opacity }}>
      <FlowLabel x={x} y={y} anchor="start">
        {typed.join("")}
      </FlowLabel>
      <motion.g style={{ opacity: caretOpacity }}>
        <rect
          x={caretX + 1}
          y={y - 6}
          width={1}
          height={12}
          className="fill-primary"
        />
      </motion.g>
    </motion.g>
  )
}

/** 不带光点的静态连线，用来画背景关系、备用路径；可选在 `at` 淡入。 */
function FlowEdge({
  route: { d },
  at,
  dashed = false,
}: {
  /** 由 `flowRoute` 生成的路径 */
  route: FlowRoute
  /** 淡入的时刻（秒），不传则一直显示 */
  at?: number
  /**
   * 是否画成虚线，表示可选或备用的路径
   * @default false
   */
  dashed?: boolean
}) {
  const line = (
    <path
      data-slot="flow-edge"
      d={d}
      strokeWidth={1}
      strokeDasharray={dashed ? "3 3" : undefined}
      className="stroke-foreground/20"
    />
  )
  return at === undefined ? line : <FlowReveal at={at}>{line}</FlowReveal>
}

/** 旋转的加载圈，只在 `at` 到 `until` 之间显示。`x`、`y` 是中心点。 */
function FlowSpinner({
  x,
  y,
  at,
  until,
  size = 12,
  tone = "primary",
}: {
  /** 中心点的横坐标 */
  x: number
  /** 中心点的纵坐标 */
  y: number
  /** 开始显示的时刻（秒） */
  at: number
  /** 消失的时刻（秒），不传则停留到本轮淡出 */
  until?: number
  /**
   * 外径（设计尺寸中的像素）
   * @default 12
   */
  size?: number
  /**
   * 圆环颜色
   * @default "primary"
   */
  tone?: FlowTone
}) {
  const { time, exit, duration } = useFlowClock()
  const end = until ?? exit
  const opacity = useTransform(
    time,
    [at, at + 0.15, end, end + 0.2, duration],
    [0, 1, 1, 0, 0],
  )
  const rotate = useTransform(time, (value) => value * 540)
  const radius = size / 2 - 1
  const circumference = 2 * Math.PI * radius
  return (
    <motion.g data-slot="flow-spinner" style={{ opacity }}>
      <motion.g
        style={{ rotate, transformBox: "fill-box", transformOrigin: "center" }}
      >
        <circle
          cx={x}
          cy={y}
          r={radius}
          strokeWidth={1.5}
          strokeLinecap="round"
          strokeDasharray={`${circumference * 0.7} ${circumference}`}
          className={toneClasses[tone].stroke}
        />
      </motion.g>
    </motion.g>
  )
}

/** 状态点：到 `at` 时淡入；`pulse` 打开后向外扩散一圈圈涟漪。 */
function FlowStatusDot({
  x,
  y,
  at,
  radius = 2,
  tone = "primary",
  pulse = false,
}: {
  /** 圆心的横坐标 */
  x: number
  /** 圆心的纵坐标 */
  y: number
  /** 淡入的时刻（秒），不传则一直显示 */
  at?: number
  /**
   * 半径（设计尺寸中的像素）
   * @default 2
   */
  radius?: number
  /**
   * 点的颜色
   * @default "primary"
   */
  tone?: FlowTone
  /**
   * 是否向外扩散涟漪，表示服务在运行
   * @default false
   */
  pulse?: boolean
}) {
  const dot = (
    <g data-slot="flow-status-dot">
      <circle cx={x} cy={y} r={radius} className={toneClasses[tone].fill} />
      {pulse ? (
        <Ripple x={x} y={y} radius={radius} at={at ?? 0} tone={tone} />
      ) : null}
    </g>
  )
  return at === undefined ? dot : <FlowReveal at={at}>{dot}</FlowReveal>
}

/** 每 1.6 秒一圈的涟漪，相位由时间推导。 */
function Ripple({
  x,
  y,
  radius,
  at,
  tone,
}: {
  x: number
  y: number
  radius: number
  at: number
  tone: FlowTone
}) {
  const { time } = useFlowClock()
  const phase = useTransform(time, (value) =>
    value < at ? 1 : ((value - at) % 1.6) / 1.6,
  )
  const r = useTransform(phase, [0, 1], [radius, radius * 3.2])
  const opacity = useTransform(phase, [0, 1], [0.5, 0])
  return (
    <motion.circle
      cx={x}
      cy={y}
      r={r}
      strokeWidth={1}
      className={cn("fill-none", toneClasses[tone].stroke)}
      style={{ opacity }}
    />
  )
}

export {
  FlowDiamond,
  FlowEdge,
  FlowLabel,
  FlowNode,
  FlowReveal,
  FlowSpinner,
  FlowStatusDot,
  FlowTypedText,
}

"use client"

import { motion, useTransform } from "motion/react"

import { useFlowClock } from "./flow-clock"
import { FLOW_BEAM_SPEED, type FlowRoute } from "./route"
import { toneClasses, type FlowTone } from "./tone"

/** 光点本体与拖尾的长度（像素） */
const HEAD_LENGTH = 8
const TAIL_LENGTH = 26

/** 连线 + 沿线流动的光点（带一小段拖尾）。 */
function FlowBeam({
  route: { d, length },
  at,
  base = true,
  tone = "primary",
}: {
  /** 由 `flowRoute` 生成的路径 */
  route: FlowRoute
  /** 光点出发的时刻（秒） */
  at: number
  /**
   * 是否同时画出底线。同一条线上的重复脉冲设为 `false`，避免底线叠加变粗
   * @default true
   */
  base?: boolean
  /**
   * 光点颜色，失败、拒绝之类的分支用 `destructive`
   * @default "primary"
   */
  tone?: FlowTone
}) {
  const { time } = useFlowClock()
  const end = at + (length + TAIL_LENGTH) / FLOW_BEAM_SPEED
  // 光点头部沿路径走过的距离；超出终点的部分让拖尾也走完
  const head = useTransform(time, [at, end], [0, length + TAIL_LENGTH])
  const headOffset = useTransform(
    head,
    (value) => (value - HEAD_LENGTH) / length,
  )
  const tailOffset = useTransform(
    head,
    (value) => (value - TAIL_LENGTH) / length,
  )
  const headOpacity = useTransform(time, (value) =>
    value > at && value < end ? 1 : 0,
  )
  const tailOpacity = useTransform(time, (value) =>
    value > at && value < end ? 0.35 : 0,
  )
  const stroke = toneClasses[tone].stroke

  return (
    <g data-slot="flow-beam">
      {base ? (
        <path d={d} strokeWidth={1} className="stroke-foreground/20" />
      ) : null}
      <motion.path
        d={d}
        strokeWidth={1.5}
        strokeLinecap="round"
        className={stroke}
        style={{
          pathLength: TAIL_LENGTH / length,
          pathSpacing: 2,
          pathOffset: tailOffset,
          opacity: tailOpacity,
        }}
      />
      <motion.path
        d={d}
        strokeWidth={2}
        strokeLinecap="round"
        className={stroke}
        style={{
          pathLength: HEAD_LENGTH / length,
          pathSpacing: 2,
          pathOffset: headOffset,
          opacity: headOpacity,
        }}
      />
    </g>
  )
}

export { FlowBeam }

// 纯函数，不依赖 React：服务端组件也可以直接调用

/** 光点飞行速度（像素/秒）：各段耗时由路径长度换算，同一张图里节奏才一致 */
const FLOW_BEAM_SPEED = 110
type FlowPoint = readonly [number, number]
type FlowRoute = { d: string; length: number }

function round(value: number) {
  return Math.round(value * 100) / 100
}

/**
 * 把折线变成圆角路径，并返回近似长度。
 * 长度要提前知道：光点的出现和到达时间都靠它换算，不用在浏览器里量。
 * 建议在组件外调用，每次渲染重新计算没有意义。
 */
function flowRoute(points: readonly FlowPoint[], radius = 6): FlowRoute {
  let d = `M${points[0][0]} ${points[0][1]}`
  let length = 0
  for (let index = 1; index < points.length; index += 1) {
    const [px, py] = points[index - 1]
    const [cx, cy] = points[index]
    const next = points[index + 1]
    const incoming = Math.hypot(cx - px, cy - py)
    length += incoming
    if (!next) {
      d += ` L${cx} ${cy}`
      continue
    }
    const [nx, ny] = next
    const outgoing = Math.hypot(nx - cx, ny - cy)
    const corner = Math.min(radius, incoming / 2, outgoing / 2)
    const inX = (cx - px) / incoming
    const inY = (cy - py) / incoming
    const outX = (nx - cx) / outgoing
    const outY = (ny - cy) / outgoing
    d += ` L${round(cx - inX * corner)} ${round(cy - inY * corner)}`
    d += ` Q${cx} ${cy} ${round(cx + outX * corner)} ${round(cy + outY * corner)}`
    // 二次贝塞尔拐角比两条直角边短约 0.4 倍半径
    length -= 0.4 * corner
  }
  return { d, length: round(length) }
}

/** 光点从 `at` 出发后到达终点的时刻，用来点亮目标节点。 */
function flowArrival(at: number, { length }: FlowRoute) {
  return at + length / FLOW_BEAM_SPEED
}

export { FLOW_BEAM_SPEED, flowArrival, flowRoute }
export type { FlowPoint, FlowRoute }

"use client"

import { createContext, useContext } from "react"
import type { MotionValue } from "motion/react"

type FlowClock = {
  /** 当前循环内的时间（秒） */
  time: MotionValue<number>
  /** 一轮循环的总时长（秒） */
  duration: number
  /** 从这一刻起动态内容淡出，循环末尾回到起点 */
  exit: number
}

const FlowClockContext = createContext<FlowClock | null>(null)

/** 读取 `FlowDiagram` 提供的时间轴，用来写自定义的动画元素。 */
function useFlowClock() {
  const clock = useContext(FlowClockContext)
  if (!clock) throw new Error("useFlowClock 只能在 FlowDiagram 内使用")
  return clock
}

export { FlowClockContext, useFlowClock }
export type { FlowClock }

/** 点亮、光点、状态点可用的色调；只引用主题 token，跟随颜色主题变化。 */
